local function loadStatsPro(locale, opts)
    local env = makeEnv(locale, opts)
    local addon = {
        __statsproSmoke = true,
        __testWelcomeEnabled = opts and opts.testWelcomeEnabled == true,
    }
    local chunk, loadErr = loadfile("StatsPro.lua")
    if not chunk then error(loadErr, 0) end
    setfenv(chunk, env)
    local ok, runtimeErr = pcall(chunk, "StatsPro", addon)
    if not ok then error(runtimeErr, 0) end
    if not addon.__test then
        error("missing addon.__test; StatsPro smoke bridge was not initialized", 0)
    end
    return env, addon, addon.__test
end

local function withProfileIdentity(opts)
    opts = opts or {}
    opts.unitGUID = opts.unitGUID or function() return "Player-1-IMPORT" end
    opts.getSpecialization = opts.getSpecialization or function() return 1 end
    opts.specID = opts.specID or 73
    opts.specName = opts.specName or "Protection"
    opts.specRole = opts.specRole or "TANK"
    opts.primaryStat = opts.primaryStat or 1
    return opts
end

local function loadFocusedStatScenario(dbDefaults, dbOverrides, apiOverrides)
    local statsProDB = {}
    for key, value in pairs(dbDefaults) do
        statsProDB[key] = value
    end
    for key, value in pairs(dbOverrides or {}) do
        statsProDB[key] = value
    end

    local options = {}
    for key, value in pairs(apiOverrides or {}) do
        options[key] = value
    end
    options.statsProDB = statsProDB
    return loadStatsPro("enUS", options)
end

local function loadCritScenario(dbOverrides, apiOverrides)
    return loadFocusedStatScenario({
        showOffensive = true,
        showCrit = true,
        showHaste = false,
        showMastery = false,
        showVersatility = false,
        showTertiary = false,
        showDefensive = false,
    }, dbOverrides, apiOverrides)
end

local function loadDefensiveScenario(dbOverrides, apiOverrides)
    return loadFocusedStatScenario({
        showOffensive = false,
        showDefensive = true,
        hideZeroDefensive = false,
        showDodge = false,
        showParry = false,
    }, dbOverrides, apiOverrides)
end

