    root.profiles.p4 = { name = "Other", settings = deepCopy(active) }
    root.account.nextProfileID = 5
    root.profiles.p4.settings.scale = 1.3
    local otherBefore = deepCopy(root.profiles.p4)
    local accountBefore = deepCopy(root.account)
