        "StatsProStaminaCheck",
        "StatsProOffensiveCheck",
        "StatsProHideZeroOffCheck",
        "StatsProCritCheck",
        "StatsProHasteCheck",
        "StatsProMasteryCheck",
        "StatsProVersCheck",
