do
    assertNoSharedTables("db_compat.registry_fixture.fresh_graph",
        test.makeRegistryFixture(), test.makeRegistryFixture())

    local validCharacterDB = test.makeRegistryFixture()
    validCharacterDB.characters["Player-1-00000001"] = {
        displayName = "Tester-Realm",
        classID = 10,
        lastSeen = 12345,
        defaultProfileID = "p1",
        specProfiles = { [268] = "p2" },
    }
    local validEnv, _, validTest = loadStatsPro("enUS", { statsProDB = validCharacterDB })
    fireEvent("db_compat.registry_validation.valid_character", validEnv, "PLAYER_ENTERING_WORLD")
    eq("db_compat.registry_validation.valid_character_mode",
        validTest.dbCompatibilityState().mode, "current")

    local cases = {
        {
            name = "shadow_alias",
            mutate = function(db) db.profiles.p1.settings.colors = db.colors end,
        },
        {
            name = "shadow_key_alias",
            mutate = function(db)
                db.shadowKey = { [db.profiles.p1.settings.colors] = true }
            end,
        },
        {
            name = "root_shadow_key_alias",
            mutate = function(db)
                db[db.profiles.p1.settings.colors] = true
            end,
        },
        {
            name = "profile_nested_alias",
            mutate = function(db)
                db.profiles.p2.settings.colors = db.profiles.p1.settings.colors
            end,
        },
        {
            name = "profile_settings_alias",
            mutate = function(db) db.profiles.p2.settings = db.profiles.p1.settings end,
        },
        {
            name = "account_settings_alias",
            mutate = function(db) db.profiles.p1.settings = db.account end,
        },
        {
            name = "profile_account_setting",
            mutate = function(db) db.profiles.p1.settings.quickSetupSeen = true end,
        },
        {
            name = "malformed_unreferenced_profile",
            mutate = function(db) db.profiles.p2.name = 42 end,
        },
        {
            name = "next_id_collision",
            mutate = function(db) db.account.nextProfileID = 2 end,
        },
        {
            name = "next_id_scientific_notation",
            mutate = function(db) db.account.nextProfileID = 100000000000000 end,
        },
        {
            name = "invalid_account_interval",
            mutate = function(db) db.account.updateInterval = 7 end,
        },
        {
            name = "missing_character_assignment",
            mutate = function(db)
                db.characters["Player-1-00000001"] = {
                    defaultProfileID = "p1",
                    specProfiles = { [268] = "missing" },
                }
            end,
        },
    }
    for _, case in ipairs(cases) do
        local db = test.makeRegistryFixture()
        case.mutate(db)
        local before = deepCopy(db)
        local rootRef = db
        local accountRef = db.account
        local profilesRef = db.profiles
        local rolesRef = db.roleTemplates
        local charactersRef = db.characters
        local p2Ref = db.profiles.p2
        local p1SettingsRef = db.profiles.p1.settings
        local p1ColorsRef = db.profiles.p1.settings.colors
        local p2SettingsRef = db.profiles.p2.settings
        local p2ColorsRef = db.profiles.p2.settings.colors
        local shadowColorsRef = db.colors
        local shadowCritRef = db.colors.crit
        local shadowKeyRef = db.shadowKey
        local characterKey, characterRef = next(db.characters)
        local specProfilesRef = characterRef and characterRef.specProfiles or nil
        local envCase, _, caseTest = loadStatsPro("enUS", { statsProDB = db })
        local ok, err = pcall(envCase.__fireEvent, "PLAYER_ENTERING_WORLD")
        check("db_compat.registry_validation." .. case.name .. ".no_error", ok, err)
        eq("db_compat.registry_validation." .. case.name .. ".mode",
            caseTest.dbCompatibilityState().mode, "corrupt")
        slash("db_compat.registry_validation." .. case.name .. ".reset", envCase, "reset")
        fireEvent("db_compat.registry_validation." .. case.name .. ".logout",
            envCase, "PLAYER_LOGOUT")
        eq("db_compat.registry_validation." .. case.name .. ".root_identity",
            rawequal(envCase.StatsProDB, rootRef), true)
        eq("db_compat.registry_validation." .. case.name .. ".account_identity",
            rawequal(db.account, accountRef), true)
        eq("db_compat.registry_validation." .. case.name .. ".profiles_identity",
            rawequal(db.profiles, profilesRef), true)
        eq("db_compat.registry_validation." .. case.name .. ".roles_identity",
            rawequal(db.roleTemplates, rolesRef), true)
        eq("db_compat.registry_validation." .. case.name .. ".characters_identity",
            rawequal(db.characters, charactersRef), true)
        eq("db_compat.registry_validation." .. case.name .. ".other_profile_identity",
            rawequal(db.profiles.p2, p2Ref), true)
        eq("db_compat.registry_validation." .. case.name .. ".settings_identity",
            rawequal(db.profiles.p1.settings, p1SettingsRef), true)
        eq("db_compat.registry_validation." .. case.name .. ".p1_colors_identity",
            rawequal(db.profiles.p1.settings.colors, p1ColorsRef), true)
        eq("db_compat.registry_validation." .. case.name .. ".p2_settings_identity",
            rawequal(db.profiles.p2.settings, p2SettingsRef), true)
        eq("db_compat.registry_validation." .. case.name .. ".p2_colors_identity",
            rawequal(db.profiles.p2.settings.colors, p2ColorsRef), true)
        eq("db_compat.registry_validation." .. case.name .. ".shadow_colors_identity",
            rawequal(db.colors, shadowColorsRef), true)
        eq("db_compat.registry_validation." .. case.name .. ".shadow_crit_identity",
            rawequal(db.colors.crit, shadowCritRef), true)
        if characterRef then
            eq("db_compat.registry_validation." .. case.name .. ".character_identity",
                rawequal(db.characters[characterKey], characterRef), true)
            eq("db_compat.registry_validation." .. case.name .. ".spec_profiles_identity",
                rawequal(characterRef.specProfiles, specProfilesRef), true)
        end
        if case.name == "shadow_key_alias" then
            local shadowAliasKey, shadowAliasValue = next(db.shadowKey)
            eq("db_compat.registry_validation.shadow_key_alias.shadow_identity",
                rawequal(db.shadowKey, shadowKeyRef), true)
            eq("db_compat.registry_validation.shadow_key_alias.key_identity",
                rawequal(shadowAliasKey, p1ColorsRef), true)
            eq("db_compat.registry_validation.shadow_key_alias.value_unchanged",
                shadowAliasValue, true)
        elseif case.name == "root_shadow_key_alias" then
            local rootAliasValue
            for key, value in pairs(db) do
                if rawequal(key, p1ColorsRef) then rootAliasValue = value; break end
            end
            eq("db_compat.registry_validation.root_shadow_key_alias.value_unchanged",
                rootAliasValue, true)
        else
            assertDeepEqual("db_compat.registry_validation." .. case.name .. ".no_writes",
                db, before)
        end
    end

    local boundaryCases = {
        {
            name = "account",
            mutate = function(db) db.account = deepCopy(db.account) end,
        },
        {
            name = "profiles",
            mutate = function(db) db.profiles = deepCopy(db.profiles) end,
        },
        {
            name = "roles",
            mutate = function(db) db.roleTemplates = deepCopy(db.roleTemplates) end,
        },
        {
            name = "characters",
            mutate = function(db) db.characters = deepCopy(db.characters) end,
        },
        {
            name = "default_profile",
            mutate = function(db) db.profiles.p1 = deepCopy(db.profiles.p1) end,
        },
        {
            name = "active_settings",
            mutate = function(db)
                db.profiles.p1.settings = deepCopy(db.profiles.p1.settings)
            end,
        },
    }
    for _, boundary in ipairs(boundaryCases) do
        local db = test.makeRegistryFixture()
        local boundaryEnv, _, boundaryTest = loadStatsPro("enUS", { statsProDB = db })
        fireEvent("db_compat.validation_cache." .. boundary.name .. ".pew",
            boundaryEnv, "PLAYER_ENTERING_WORLD")
        local countBefore = boundaryTest.dbValidationCount()
        boundary.mutate(db)
        local state = boundaryTest.dbCompatibilityState()
        eq("db_compat.validation_cache." .. boundary.name .. ".revalidated",
            boundaryTest.dbValidationCount(), countBefore + 1)
        eq("db_compat.validation_cache." .. boundary.name .. ".current",
            state.mode, "current")
        boundaryTest.dbCompatibilityState()
        eq("db_compat.validation_cache." .. boundary.name .. ".recached",
            boundaryTest.dbValidationCount(), countBefore + 1)
    end

    local missingScopeDB = test.makeRegistryFixture()
    local missingScopeEnv, _, missingScopeTest = loadStatsPro(
        "enUS", { statsProDB = missingScopeDB })
    fireEvent("db_compat.validation_cache.account_wide_missing.pew",
        missingScopeEnv, "PLAYER_ENTERING_WORLD")
    local missingScopeCount = missingScopeTest.dbValidationCount()
    missingScopeDB.account.accountWideEnabled = nil
    local missingScopeState = missingScopeTest.dbCompatibilityState()
    eq("db_compat.validation_cache.account_wide_missing.revalidated",
        missingScopeTest.dbValidationCount(), missingScopeCount + 1)
    eq("db_compat.validation_cache.account_wide_missing.corrupt",
        missingScopeState.mode, "corrupt")

    local malformedDB = test.makeRegistryFixture()
    local malformedEnv, _, malformedTest = loadStatsPro("enUS", { statsProDB = malformedDB })
    fireEvent("db_compat.validation_cache.malformed.pew", malformedEnv, "PLAYER_ENTERING_WORLD")
    local malformedCount = malformedTest.dbValidationCount()
    malformedDB.roleTemplates = { TANK = "missing", HEALER = "p1", DAMAGER = "p2" }
    local malformedBeforeWrite = deepCopy(malformedDB)
    slash("db_compat.validation_cache.malformed.write", malformedEnv, "show")
    eq("db_compat.validation_cache.malformed.revalidated",
        malformedTest.dbValidationCount(), malformedCount + 1)
    eq("db_compat.validation_cache.malformed.corrupt",
        malformedTest.dbCompatibilityState().mode, "corrupt")
    assertDeepEqual("db_compat.validation_cache.malformed.write_blocked",
        malformedDB, malformedBeforeWrite)

    local secretLocale = "secret-locale"
    local secretAccountDB = test.makeRegistryFixture()
    secretAccountDB.account.forceLocale = secretLocale
    local secretAccountBefore = deepCopy(secretAccountDB)
    local secretAccountRef = secretAccountDB.account
    local secretAccountProfilesRef = secretAccountDB.profiles
    local secretAccountSettingsRef = secretAccountDB.profiles.p1.settings
    local secretAccountColorsRef = secretAccountDB.profiles.p1.settings.colors
    local secretAccountRolesRef = secretAccountDB.roleTemplates
    local secretAccountCharactersRef = secretAccountDB.characters
    local secretAccountEnv, _, secretAccountTest = loadStatsPro("enUS", {
        statsProDB = secretAccountDB,
        issecretvalue = function(value) return value == secretLocale end,
    })
    local ok, err = pcall(secretAccountEnv.__fireEvent, "PLAYER_ENTERING_WORLD")
    check("db_compat.registry_validation.secret_account.no_error", ok, err)
    eq("db_compat.registry_validation.secret_account.mode",
        secretAccountTest.dbCompatibilityState().mode, "corrupt")
    eq("db_compat.registry_validation.secret_account.account_identity",
        rawequal(secretAccountDB.account, secretAccountRef), true)
    eq("db_compat.registry_validation.secret_account.profiles_identity",
        rawequal(secretAccountDB.profiles, secretAccountProfilesRef), true)
    eq("db_compat.registry_validation.secret_account.settings_identity",
        rawequal(secretAccountDB.profiles.p1.settings, secretAccountSettingsRef), true)
    eq("db_compat.registry_validation.secret_account.colors_identity",
        rawequal(secretAccountDB.profiles.p1.settings.colors, secretAccountColorsRef), true)
    eq("db_compat.registry_validation.secret_account.roles_identity",
        rawequal(secretAccountDB.roleTemplates, secretAccountRolesRef), true)
    eq("db_compat.registry_validation.secret_account.characters_identity",
        rawequal(secretAccountDB.characters, secretAccountCharactersRef), true)
    assertDeepEqual("db_compat.registry_validation.secret_account.no_writes",
        secretAccountDB, secretAccountBefore)

    local secretColors = {}
    local secretNestedDB = test.makeRegistryFixture()
    secretNestedDB.profiles.p1.settings.colors = secretColors
    local secretNestedBefore = deepCopy(secretNestedDB)
    local secretNestedAccountRef = secretNestedDB.account
    local secretNestedProfilesRef = secretNestedDB.profiles
    local secretNestedSettingsRef = secretNestedDB.profiles.p1.settings
    local secretNestedRolesRef = secretNestedDB.roleTemplates
    local secretNestedCharactersRef = secretNestedDB.characters
    local secretNestedEnv, _, secretNestedTest = loadStatsPro("enUS", {
        statsProDB = secretNestedDB,
        issecrettable = function(value) return value == secretColors end,
    })
    ok, err = pcall(secretNestedEnv.__fireEvent, "PLAYER_ENTERING_WORLD")
    check("db_compat.registry_validation.secret_nested.no_error", ok, err)
    eq("db_compat.registry_validation.secret_nested.mode",
        secretNestedTest.dbCompatibilityState().mode, "corrupt")
    eq("db_compat.registry_validation.secret_nested.account_identity",
        rawequal(secretNestedDB.account, secretNestedAccountRef), true)
    eq("db_compat.registry_validation.secret_nested.profiles_identity",
        rawequal(secretNestedDB.profiles, secretNestedProfilesRef), true)
    eq("db_compat.registry_validation.secret_nested.settings_identity",
        rawequal(secretNestedDB.profiles.p1.settings, secretNestedSettingsRef), true)
    eq("db_compat.registry_validation.secret_nested.colors_identity",
        rawequal(secretNestedDB.profiles.p1.settings.colors, secretColors), true)
    eq("db_compat.registry_validation.secret_nested.roles_identity",
        rawequal(secretNestedDB.roleTemplates, secretNestedRolesRef), true)
    eq("db_compat.registry_validation.secret_nested.characters_identity",
        rawequal(secretNestedDB.characters, secretNestedCharactersRef), true)
    assertDeepEqual("db_compat.registry_validation.secret_nested.no_writes",
        secretNestedDB, secretNestedBefore)
end

do
    local corruptGuidance = "StatsPro saved data is corrupted and remains read-only. Use /ss wipe outside combat to reset it."
    local corruptControlCopy = "Corrupted data - profiles are read-only. Use /ss wipe to reset."
    local corruptPrompt = "Reset corrupted StatsPro data? This permanently removes every profile, character and specialization assignment, role template, account setting, and saved position."
    local futureGuidance = "Settings are read-only because they were saved by a newer StatsPro version. Update StatsPro to change them."

    local function newCorruptRoot()
        return {
            dbVersion = test.currentDBVersion(),
            account = {
                forceLocale = "auto",
                updateInterval = 0.5,
                defaultProfileID = "missing",
                nextProfileID = 2,
            },
            roleTemplates = { TANK = "missing", HEALER = "missing", DAMAGER = "missing" },
            characters = {},
            damagedPayload = { keep = true },
        }
    end

    local corruptLoadCount = 0
    local function loadCorruptRoot()
        corruptLoadCount = corruptLoadCount + 1
        local root = newCorruptRoot()
        local combat = { value = false }
        local env, addonContext, corruptTest = loadStatsPro("enUS", {
            statsProDB = root,
            inCombatLockdown = function() return combat.value end,
        })
        fireEvent("db_compat.corrupt_recovery.pew." .. corruptLoadCount,
            env, "PLAYER_ENTERING_WORLD")
        return env, addonContext, corruptTest, root, combat
    end

    local function expectedFreshRoot(corruptTest)
        local settings = corruptTest.copyDefaults()
        local forceLocale = settings.forceLocale
        local updateInterval = settings.updateInterval
        settings.forceLocale = nil
        settings.updateInterval = nil
        settings.quickSetupSeen = nil
        return {
            dbVersion = corruptTest.currentDBVersion(),
            account = {
                forceLocale = forceLocale,
                updateInterval = updateInterval,
                quickSetupSeen = true,
                defaultProfileID = "p1",
                nextProfileID = 2,
                accountWideEnabled = false,
            },
            profiles = { p1 = { name = "Default", settings = settings } },
            roleTemplates = { TANK = "p1", HEALER = "p1", DAMAGER = "p1" },
            characters = {},
        }
    end

    do
        local env, addonContext, corruptTest, root, combat = loadCorruptRoot()
        local before = deepCopy(root)
        local operationBefore = corruptTest.profileOps.state().operationCount
        local structuralBefore = corruptTest.profileRuntimeState().structuralCommitCount

        clearPrints(env)
        slash("db_compat.corrupt_recovery.guidance", env, "show")
        eq("db_compat.corrupt_recovery.guidance_specific",
            printContains(env, corruptGuidance), true)
        eq("db_compat.corrupt_recovery.guidance_not_future",
            printContains(env, futureGuidance), false)
        eq("db_compat.corrupt_recovery.warned_mode",
            corruptTest.dbCompatibilityState().warnedMode, "corrupt")
        local configOK, configError = pcall(function() addonContext:OpenConfigMenu() end)
        check("db_compat.corrupt_recovery.config_open", configOK, configError)
        eq("db_compat.corrupt_recovery.config_copy",
            corruptTest.profileUIState().headerProfile, corruptControlCopy)
        addonContext:OpenConfigMenu()

        slash("db_compat.corrupt_recovery.cancel.request", env, "wipe")
        eq("db_compat.corrupt_recovery.cancel.popup", env.__lastStaticPopup.key,
            "STATSPRO_WIPE_ALL_DATA")
        eq("db_compat.corrupt_recovery.cancel.prompt",
            env.__lastStaticPopup.definition.text, corruptPrompt)
        eq("db_compat.corrupt_recovery.cancel.pending",
            corruptTest.destructivePromptState().wipePending, true)
        eq("db_compat.corrupt_recovery.cancel.kind",
            corruptTest.destructivePromptState().wipeCorruptRecovery, true)
        assertDeepEqual("db_compat.corrupt_recovery.cancel.request_zero_writes", root, before)
        env.__cancelStaticPopup()
        eq("db_compat.corrupt_recovery.cancel.pending_cleared",
            corruptTest.destructivePromptState().wipePending, false)
        assertDeepEqual("db_compat.corrupt_recovery.cancel.zero_writes", root, before)

        slash("db_compat.corrupt_recovery.accept_combat.request", env, "wipe")
        combat.value = true
        env.__acceptStaticPopup()
        eq("db_compat.corrupt_recovery.accept_combat.same_root",
            rawequal(env.StatsProDB, root), true)
        eq("db_compat.corrupt_recovery.accept_combat.mode",
            corruptTest.dbCompatibilityState().mode, "corrupt")
        assertDeepEqual("db_compat.corrupt_recovery.accept_combat.zero_writes", root, before)

        local popupCount = env.__staticPopupShows
        slash("db_compat.corrupt_recovery.combat", env, "wipe")
        eq("db_compat.corrupt_recovery.combat.no_popup",
            env.__staticPopupShows, popupCount)
        eq("db_compat.corrupt_recovery.combat.no_pending",
            corruptTest.destructivePromptState().wipePending, false)
        assertDeepEqual("db_compat.corrupt_recovery.combat.zero_writes", root, before)

        combat.value = false
        slash("db_compat.corrupt_recovery.accept.request", env, "wipe")
        assertDeepEqual("db_compat.corrupt_recovery.accept.request_zero_writes", root, before)
        env.__acceptStaticPopup()
        local freshRoot = env.StatsProDB
        eq("db_compat.corrupt_recovery.accept.root_replaced", rawequal(freshRoot, root), false)
        assertDeepEqual("db_compat.corrupt_recovery.accept.old_root_untouched", root, before)
        assertDeepEqual("db_compat.corrupt_recovery.accept.exact_defaults",
            freshRoot, expectedFreshRoot(corruptTest))
        local recovered = corruptTest.dbCompatibilityState()
        eq("db_compat.corrupt_recovery.accept.mode", recovered.mode, "current")
        eq("db_compat.corrupt_recovery.accept.writable", recovered.readOnly, false)
        eq("db_compat.corrupt_recovery.accept.warning_cleared", recovered.warnedMode, nil)
        eq("db_compat.corrupt_recovery.accept.operation_count",
            corruptTest.profileOps.state().operationCount, operationBefore + 1)
        eq("db_compat.corrupt_recovery.accept.structural_count",
            corruptTest.profileRuntimeState().structuralCommitCount, structuralBefore + 1)
        eq("db_compat.corrupt_recovery.accept.no_pending",
            corruptTest.destructivePromptState().wipePending, false)
    end

    do
        local secretCombat = {}
        local root = newCorruptRoot()
        local before = deepCopy(root)
        local env, _, corruptTest = loadStatsPro("enUS", {
            statsProDB = root,
            inCombatLockdown = function() return secretCombat end,
            issecretvalue = function(value) return rawequal(value, secretCombat) end,
        })
        fireEvent("db_compat.corrupt_recovery.unknown_combat.pew",
            env, "PLAYER_ENTERING_WORLD")
        slash("db_compat.corrupt_recovery.unknown_combat.request", env, "wipe")
        eq("db_compat.corrupt_recovery.unknown_combat.no_popup",
            env.__staticPopupShows, 0)
        eq("db_compat.corrupt_recovery.unknown_combat.no_pending",
            corruptTest.destructivePromptState().wipePending, false)
        assertDeepEqual("db_compat.corrupt_recovery.unknown_combat.zero_writes", root, before)
    end

    do
        local env, _, corruptTest, root = loadCorruptRoot()
        local oldBefore = deepCopy(root)
        slash("db_compat.corrupt_recovery.stale_root.request", env, "wipe")
        local replacement = newCorruptRoot()
        local replacementBefore = deepCopy(replacement)
        env.StatsProDB = replacement
        env.__acceptStaticPopup()
        eq("db_compat.corrupt_recovery.stale_root.old_identity",
            rawequal(env.StatsProDB, root), false)
        assertDeepEqual("db_compat.corrupt_recovery.stale_root.old_unchanged", root, oldBefore)
        assertDeepEqual("db_compat.corrupt_recovery.stale_root.new_unchanged",
            replacement, replacementBefore)
        eq("db_compat.corrupt_recovery.stale_root.mode",
            corruptTest.dbCompatibilityState().mode, "corrupt")
    end

    do
        local env, _, corruptTest, root = loadCorruptRoot()
        clearPrints(env)
        slash("db_compat.corrupt_recovery.future_transition.guidance", env, "show")
        eq("db_compat.corrupt_recovery.future_transition.warned_corrupt",
            corruptTest.dbCompatibilityState().warnedMode, "corrupt")
        slash("db_compat.corrupt_recovery.future_transition.request", env, "wipe")
        root.dbVersion = corruptTest.currentDBVersion() + 1
        local futureBefore = deepCopy(root)
        env.__acceptStaticPopup()
        eq("db_compat.corrupt_recovery.future_transition.same_root",
            rawequal(env.StatsProDB, root), true)
        assertDeepEqual("db_compat.corrupt_recovery.future_transition.zero_writes",
            root, futureBefore)
        eq("db_compat.corrupt_recovery.future_transition.mode",
            corruptTest.dbCompatibilityState().mode, "future")
        clearPrints(env)
        slash("db_compat.corrupt_recovery.future_transition.show", env, "show")
        eq("db_compat.corrupt_recovery.future_transition.future_guidance",
            printContains(env, futureGuidance), true)
        eq("db_compat.corrupt_recovery.future_transition.warned_future",
            corruptTest.dbCompatibilityState().warnedMode, "future")
        local popupCount = env.__staticPopupShows
        slash("db_compat.corrupt_recovery.future_transition.wipe_blocked", env, "wipe")
        eq("db_compat.corrupt_recovery.future_transition.no_new_popup",
            env.__staticPopupShows, popupCount)
        assertDeepEqual("db_compat.corrupt_recovery.future_transition.still_unchanged",
            root, futureBefore)
    end

    for _, stage in ipairs({ "validate", "commit", "apply" }) do
        local env, _, corruptTest, root = loadCorruptRoot()
        local before = deepCopy(root)
        local operationBefore = corruptTest.profileOps.state().operationCount
        corruptTest.profileOps.setFailureStage(stage)
        slash("db_compat.corrupt_recovery.failure." .. stage .. ".request", env, "wipe")
        env.__acceptStaticPopup()
        eq("db_compat.corrupt_recovery.failure." .. stage .. ".root_identity",
            rawequal(env.StatsProDB, root), true)
        assertDeepEqual("db_compat.corrupt_recovery.failure." .. stage .. ".rollback",
            root, before)
        local failedState = corruptTest.dbCompatibilityState()
        eq("db_compat.corrupt_recovery.failure." .. stage .. ".mode",
            failedState.mode, "corrupt")
        eq("db_compat.corrupt_recovery.failure." .. stage .. ".read_only",
            failedState.readOnly, true)
        eq("db_compat.corrupt_recovery.failure." .. stage .. ".operation_count",
            corruptTest.profileOps.state().operationCount, operationBefore)

        slash("db_compat.corrupt_recovery.failure." .. stage .. ".retry", env, "wipe")
        env.__acceptStaticPopup()
        eq("db_compat.corrupt_recovery.failure." .. stage .. ".retry_mode",
            corruptTest.dbCompatibilityState().mode, "current")
        assertDeepEqual("db_compat.corrupt_recovery.failure." .. stage .. ".retry_defaults",
            env.StatsProDB, expectedFreshRoot(corruptTest))
    end

    do
        local env, _, corruptTest, root, combat = loadCorruptRoot()
        local before = deepCopy(root)
        local oldSetPoint = env.StatsProFrame.SetPoint
        rawset(env.StatsProFrame, "SetPoint", function()
            error("injected corrupt recovery target and rollback apply failure")
        end)
        slash("db_compat.corrupt_recovery.rollback_retry.request", env, "wipe")
        env.__acceptStaticPopup()
        local failed = corruptTest.profileRuntimeState()
        eq("db_compat.corrupt_recovery.rollback_retry.same_root",
            rawequal(env.StatsProDB, root), true)
        assertDeepEqual("db_compat.corrupt_recovery.rollback_retry.root", root, before)
        eq("db_compat.corrupt_recovery.rollback_retry.force", failed.forceReapply, true)
        eq("db_compat.corrupt_recovery.rollback_retry.scheduled",
            failed.corruptRollbackRetryScheduled, true)
        eq("db_compat.corrupt_recovery.rollback_retry.count_before_timer",
            failed.corruptRollbackRetryCount, 0)
        eq("db_compat.corrupt_recovery.rollback_retry.root_tracked",
            rawequal(failed.corruptRollbackRoot, root), true)

        combat.value = true
        env.__flushTimers(1)
        local deferred = corruptTest.profileRuntimeState()
        eq("db_compat.corrupt_recovery.rollback_retry.combat_not_scheduled",
            deferred.corruptRollbackRetryScheduled, false)
        eq("db_compat.corrupt_recovery.rollback_retry.combat_not_consumed",
            deferred.corruptRollbackRetryCount, 0)
        eq("db_compat.corrupt_recovery.rollback_retry.combat_force",
            deferred.forceReapply, true)
        assertDeepEqual("db_compat.corrupt_recovery.rollback_retry.combat_root", root, before)

        rawset(env.StatsProFrame, "SetPoint", oldSetPoint)
        combat.value = false
        fireEvent("db_compat.corrupt_recovery.rollback_retry.regen",
            env, "PLAYER_REGEN_ENABLED")
        env.__flushTimers(1)
        local recovered = corruptTest.profileRuntimeState()
        eq("db_compat.corrupt_recovery.rollback_retry.recovered_force",
            recovered.forceReapply, false)
        eq("db_compat.corrupt_recovery.rollback_retry.recovered_scheduled",
            recovered.corruptRollbackRetryScheduled, false)
        eq("db_compat.corrupt_recovery.rollback_retry.recovered_count",
            recovered.corruptRollbackRetryCount, 0)
        eq("db_compat.corrupt_recovery.rollback_retry.recovered_root",
            recovered.corruptRollbackRoot, nil)
        eq("db_compat.corrupt_recovery.rollback_retry.still_corrupt",
            corruptTest.dbCompatibilityState().mode, "corrupt")
        assertDeepEqual("db_compat.corrupt_recovery.rollback_retry.old_root_untouched",
            root, before)
    end

    do
        local env, _, corruptTest, root = loadCorruptRoot()
        local before = deepCopy(root)
        local oldSetPoint = env.StatsProFrame.SetPoint
        rawset(env.StatsProFrame, "SetPoint", function()
            error("injected persistent corrupt rollback apply failure")
        end)
        slash("db_compat.corrupt_recovery.rollback_exhaustion.request", env, "wipe")
        env.__acceptStaticPopup()
        env.__flushTimers(1)
        local exhausted = corruptTest.profileRuntimeState()
        eq("db_compat.corrupt_recovery.rollback_exhaustion.count",
            exhausted.corruptRollbackRetryCount, 3)
        eq("db_compat.corrupt_recovery.rollback_exhaustion.not_scheduled",
            exhausted.corruptRollbackRetryScheduled, false)
        eq("db_compat.corrupt_recovery.rollback_exhaustion.force",
            exhausted.forceReapply, true)
        eq("db_compat.corrupt_recovery.rollback_exhaustion.root_tracked",
            rawequal(exhausted.corruptRollbackRoot, root), true)
        eq("db_compat.corrupt_recovery.rollback_exhaustion.same_root",
            rawequal(env.StatsProDB, root), true)
        assertDeepEqual("db_compat.corrupt_recovery.rollback_exhaustion.root", root, before)
        rawset(env.StatsProFrame, "SetPoint", oldSetPoint)
    end
end

do
    local ok, err

    local secretCurrentRoot = test.makeRegistryFixture()
    local secretCurrentBefore = deepCopy(secretCurrentRoot)
    local secretCurrentAccountRef = secretCurrentRoot.account
    local secretCurrentProfilesRef = secretCurrentRoot.profiles
    local secretCurrentEnv, _, secretCurrentTest = loadStatsPro("enUS", {
        statsProDB = secretCurrentRoot,
        issecretvalue = function(value) return rawequal(value, secretCurrentRoot) end,
    })
    ok, err = pcall(secretCurrentEnv.__fireEvent, "PLAYER_ENTERING_WORLD")
    check("db_compat.registry_validation.secret_current_root.no_error", ok, err)
    eq("db_compat.registry_validation.secret_current_root.mode",
        secretCurrentTest.dbCompatibilityState().mode, "corrupt")
    eq("db_compat.registry_validation.secret_current_root.root_identity",
        rawequal(secretCurrentEnv.StatsProDB, secretCurrentRoot), true)
    eq("db_compat.registry_validation.secret_current_root.account_identity",
        rawequal(secretCurrentRoot.account, secretCurrentAccountRef), true)
    eq("db_compat.registry_validation.secret_current_root.profiles_identity",
        rawequal(secretCurrentRoot.profiles, secretCurrentProfilesRef), true)
    assertDeepEqual("db_compat.registry_validation.secret_current_root.no_writes",
        secretCurrentRoot, secretCurrentBefore)

    local secretLegacyRoot = { dbVersion = 1, fontSize = 18 }
    local secretLegacyBefore = deepCopy(secretLegacyRoot)
    local secretLegacyEnv, _, secretLegacyTest = loadStatsPro("enUS", {
        statsProDB = secretLegacyRoot,
        issecretvalue = function(value) return rawequal(value, secretLegacyRoot) end,
    })
    ok, err = pcall(secretLegacyEnv.__fireEvent, "PLAYER_ENTERING_WORLD")
    check("db_compat.registry_validation.secret_legacy_root.no_error", ok, err)
    eq("db_compat.registry_validation.secret_legacy_root.mode",
        secretLegacyTest.dbCompatibilityState().mode, "corrupt")
    eq("db_compat.registry_validation.secret_legacy_root.root_identity",
