do
    -- A first-seen context clones its role template. The outgoing profile must be
    -- settled before that clone: Color Picker previews are transactional, while
    -- the latest panel position is committed by the context switch itself.
    local identity = {
        guid = "Player-1-FIRST-SEEN",
        specID = 71,
        specName = "Arms",
        role = "DAMAGER",
    }
    local env, addonContext, contextTest = loadStatsPro("enUS", {
        unitGUID = function() return identity.guid end,
        unitFullName = function() return "FirstSeen", "Realm" end,
        getSpecialization = function() return 1 end,
        getSpecializationInfo = function()
            return identity.specID, identity.specName, nil, nil, identity.role, 1
        end,
    })
    fireEvent("profiles.context.first_seen_modal.seed", env, "PLAYER_ENTERING_WORLD")
    local root = env.StatsProDB
    local sourceProfileID = contextTest.profileState().profileID
    root.roleTemplates.DAMAGER = sourceProfileID
    local nextProfileNumber = root.account.nextProfileID

    addonContext:OpenConfigMenu()
    local critSwatch = findFrame("profiles.context.first_seen_modal.crit", env, function(frame)
        return frame.statsProColorKey == "crit" and type(frame.scripts.OnClick) == "function"
    end)
    local committedColor = deepCopy(root.profiles[sourceProfileID].settings.colors.crit)
    callScript("profiles.context.first_seen_modal.open_color", critSwatch, "OnClick")
    env.__setColorPickerRGB(0.123, 0.456, 0.789)
    env.ColorPickerFrame.colorPickerOptions.swatchFunc()
    env.StatsProFrame:ClearAllPoints()
    env.StatsProFrame:SetPoint("TOPLEFT", env.UIParent, "TOPLEFT", 246, -135)

    identity.specID, identity.specName = 72, "Fury"
    fireEvent("profiles.context.first_seen_modal.switch",
        env, "PLAYER_SPECIALIZATION_CHANGED", "player")
    env.__flushTimers(0)

    local targetProfileID = root.characters[identity.guid].specProfiles[identity.specID]
    check("profiles.context.first_seen_modal.new_profile", targetProfileID ~= sourceProfileID)
    eq("profiles.context.first_seen_modal.one_allocation",
        targetProfileID, "p" .. tostring(nextProfileNumber))
    eq("profiles.context.first_seen_modal.next_profile_id",
        root.account.nextProfileID, nextProfileNumber + 1)
    check("profiles.context.first_seen_modal.detached_settings",
        not rawequal(root.profiles[targetProfileID].settings,
            root.profiles[sourceProfileID].settings))
    check("profiles.context.first_seen_modal.detached_colors",
        not rawequal(root.profiles[targetProfileID].settings.colors,
            root.profiles[sourceProfileID].settings.colors))
    eq("profiles.context.first_seen_modal.color_closed", env.ColorPickerFrame:IsShown(), false)
    assertColor("profiles.context.first_seen_modal.source_color_restored",
        root.profiles[sourceProfileID].settings.colors.crit,
        committedColor.r, committedColor.g, committedColor.b)
    assertColor("profiles.context.first_seen_modal.target_color_committed",
        root.profiles[targetProfileID].settings.colors.crit,
        committedColor.r, committedColor.g, committedColor.b)
    eq("profiles.context.first_seen_modal.source_position_saved",
        root.profiles[sourceProfileID].settings.xOfs, 246)
    eq("profiles.context.first_seen_modal.target_position_current",
        root.profiles[targetProfileID].settings.xOfs, 246)
    eq("profiles.context.first_seen_modal.target_position_point",
        root.profiles[targetProfileID].settings.point, "TOPLEFT")
    eq("profiles.context.first_seen_modal.target_position_relative",
        root.profiles[targetProfileID].settings.relativePoint, "TOPLEFT")
    eq("profiles.context.first_seen_modal.target_position_y",
        root.profiles[targetProfileID].settings.yOfs, -135)
    local runtime = contextTest.profileRuntimeState()
    eq("profiles.context.first_seen_modal.active_spec", runtime.activeSpecID, 72)
    eq("profiles.context.first_seen_modal.active_profile",
        contextTest.profileState().profileID, targetProfileID)
    eq("profiles.context.first_seen_modal.not_pending", runtime.pendingResolution, false)
    eq("profiles.context.first_seen_modal.no_force_reapply", runtime.forceReapply, false)
end

do
    -- Cold profile bootstrap must never expose the account default while player identity
    -- is transient. Reuse a current-schema registry so every pre-resolution delta is a bug,
    -- not expected migration work.
    local coldRootCount = 0
    local function makeColdRoot(withMappedCharacter)
        coldRootCount = coldRootCount + 1
        local seed = loadStatsPro("enUS")
        fireEvent("profiles.bootstrap.seed." .. coldRootCount,
            seed, "PLAYER_ENTERING_WORLD")
        local root = deepCopy(seed.StatsProDB)
        root.profiles.p1.settings.isVisible = false
        root.profiles.p1.settings.isLocked = true
        root.profiles.p1.settings.showDurability = false
        root.profiles.p1.settings.showRepairCost = false
        root.profiles.p2 = {
            name = "Mapped profile",
            settings = deepCopy(root.profiles.p1.settings),
        }
        root.profiles.p2.settings.isVisible = true
        root.profiles.p2.settings.isLocked = false
        root.profiles.p2.settings.showItemLevel = true
        root.account.nextProfileID = 3
        root.roleTemplates.TANK = "p2"
        root.characters = {}
        if withMappedCharacter then
            root.characters["Player-1-COLD"] = {
                displayName = "Cold-Realm",
                classID = 1,
                lastSeen = 1770000000,
                defaultProfileID = "p1",
                specProfiles = { [73] = "p2" },
            }
        end
        return root
    end

    local combat = true
    local combatRoot = makeColdRoot(true)
    local combatBefore = deepCopy(combatRoot)
    local combatEnv, combatAddon, combatTest = loadStatsPro("enUS", {
        statsProDB = combatRoot,
        unitGUID = function() return "Player-1-COLD" end,
        unitFullName = function() return "Cold", "Realm" end,
        getSpecialization = function() return 1 end,
        getSpecializationInfo = function()
            return 73, "Protection", nil, nil, "TANK", 1
        end,
        inCombatLockdown = function() return combat end,
    })
    fireEvent("profiles.bootstrap.combat.pending.pew", combatEnv, "PLAYER_ENTERING_WORLD")
    local runtime = combatTest.profileRuntimeState()
    local visual = combatTest.panelVisualState()
    eq("profiles.bootstrap.combat.not_loaded", runtime.isLoaded, false)
    eq("profiles.bootstrap.combat.pending.state", runtime.pendingResolution, true)
    eq("profiles.bootstrap.combat.bootstrap_pending", runtime.bootstrapPending, true)
    eq("profiles.bootstrap.combat.no_apply", runtime.applyCount, 0)
    eq("profiles.bootstrap.combat.no_render", runtime.updateCount, 0)
    eq("profiles.bootstrap.combat.main_hidden", visual.mainShown, false)
    eq("profiles.bootstrap.combat.side_hidden", visual.sideShown, false)
    local coldTicker = findFrame("profiles.bootstrap.combat.ticker", combatEnv, function(frame)
        return frame.scripts and type(frame.scripts.OnUpdate) == "function"
    end)
    callScript("profiles.bootstrap.combat.ticker_safe", coldTicker, "OnUpdate", 999)
    eq("profiles.bootstrap.combat.ticker_no_render",
        combatTest.profileRuntimeState().updateCount, 0)
    eq("profiles.bootstrap.combat.no_claimed_active_profile",
        combatTest.profileViewModel().activeProfileID, nil)
    combatAddon:OpenConfigMenu()
    eq("profiles.bootstrap.combat.waiting_header",
        combatTest.profileUIState().headerProfile, "Switch pending until combat ends")
    eq("profiles.bootstrap.combat.pending_edit_hidden",
        combatTest.panelEditAffordanceState().main.shown, false)
    slash("profiles.bootstrap.combat.blocks_write", combatEnv, "hide")
    combatEnv.StatsProFrame:ClearAllPoints()
    combatEnv.StatsProFrame:SetPoint("TOPLEFT", combatEnv.UIParent, "TOPLEFT", 444, -555)
    fireEvent("profiles.bootstrap.combat.logout", combatEnv, "PLAYER_LOGOUT")
    assertDeepEqual("profiles.bootstrap.combat.no_writes", combatRoot, combatBefore)

    -- PLAYER_REGEN_ENABLED is authoritative even if the combat query lags for a frame.
    fireEvent("profiles.bootstrap.combat.regen", combatEnv, "PLAYER_REGEN_ENABLED")
    runtime = combatTest.profileRuntimeState()
    visual = combatTest.panelVisualState()
    eq("profiles.bootstrap.combat.loaded", runtime.isLoaded, true)
    eq("profiles.bootstrap.combat.resolved", runtime.pendingResolution, false)
    eq("profiles.bootstrap.combat.bootstrap_cleared", runtime.bootstrapPending, false)
    eq("profiles.bootstrap.combat.exact_profile", combatTest.profileState().profileID, "p2")
    eq("profiles.bootstrap.combat.one_activation", runtime.activationCount, 1)
    eq("profiles.bootstrap.combat.cold_no_warm_apply", runtime.applyCount, 0)
    eq("profiles.bootstrap.combat.one_render", runtime.updateCount, 1)
    eq("profiles.bootstrap.combat.main_shown", visual.mainShown, true)
    eq("profiles.bootstrap.combat.header_recovered",
        combatTest.profileUIState().headerProfile, "Protection - Cold-Realm")
    eq("profiles.bootstrap.combat.control_refreshed",
        combatEnv.StatsProVisibleCheck:GetChecked(), true)
    eq("profiles.bootstrap.combat.config_refreshed_once", runtime.configRefreshCount, 1)
    eq("profiles.bootstrap.combat.mapped_lock_applied",
        combatTest.panelEditAffordanceState().locked, false)
    eq("profiles.bootstrap.combat.edit_affordance_recovered",
        combatTest.panelEditAffordanceState().main.shown, true)
    local accountDefaultBeforeEdit = deepCopy(combatRoot.profiles.p1)
    clickCheckbox("profiles.bootstrap.combat.target_control", combatEnv.StatsProVisibleCheck, false)
    eq("profiles.bootstrap.combat.target_profile_written",
        combatRoot.profiles.p2.settings.isVisible, false)
    assertDeepEqual("profiles.bootstrap.combat.account_default_not_written",
        combatRoot.profiles.p1, accountDefaultBeforeEdit)

    local unknownReads = 0
    local unknownRoot = makeColdRoot(true)
    local unknownBefore = deepCopy(unknownRoot)
    local unknownEnv, _, unknownTest = loadStatsPro("enUS", {
        statsProDB = unknownRoot,
        unitGUID = function()
            unknownReads = unknownReads + 1
            if unknownReads < 3 then return nil end
            return "Player-1-COLD"
        end,
        unitFullName = function() return "Cold", "Realm" end,
        getSpecialization = function() return 1 end,
        getSpecializationInfo = function()
            return 73, "Protection", nil, nil, "TANK", 1
        end,
    })
    fireEvent("profiles.bootstrap.unknown.pending", unknownEnv, "PLAYER_ENTERING_WORLD")
    runtime = unknownTest.profileRuntimeState()
    eq("profiles.bootstrap.unknown.first_read", unknownReads, 1)
    eq("profiles.bootstrap.unknown.retry_one", runtime.contextRetryCount, 1)
    eq("profiles.bootstrap.unknown.retry_scheduled", runtime.contextRetryScheduled, true)
    eq("profiles.bootstrap.unknown.not_loaded", runtime.isLoaded, false)
    assertDeepEqual("profiles.bootstrap.unknown.no_initial_writes", unknownRoot, unknownBefore)
    unknownEnv.__flushNextTimer(0.25)
    runtime = unknownTest.profileRuntimeState()
    eq("profiles.bootstrap.unknown.second_read", unknownReads, 2)
    eq("profiles.bootstrap.unknown.retry_two", runtime.contextRetryCount, 2)
    eq("profiles.bootstrap.unknown.still_hidden",
        unknownTest.panelVisualState().mainShown, false)
    assertDeepEqual("profiles.bootstrap.unknown.no_retry_writes", unknownRoot, unknownBefore)
    unknownEnv.__flushNextTimer(0.5)
    runtime = unknownTest.profileRuntimeState()
    eq("profiles.bootstrap.unknown.third_read", unknownReads, 3)
    eq("profiles.bootstrap.unknown.loaded", runtime.isLoaded, true)
    eq("profiles.bootstrap.unknown.exact_profile", unknownTest.profileState().profileID, "p2")
    eq("profiles.bootstrap.unknown.one_activation", runtime.activationCount, 1)
    eq("profiles.bootstrap.unknown.retry_count_cleared", runtime.contextRetryCount, 0)
    eq("profiles.bootstrap.unknown.retry_token_cleared", runtime.contextRetryScheduled, false)

    local exhaustedReady = false
    local exhaustedRoot = makeColdRoot(false)
    local exhaustedBefore = deepCopy(exhaustedRoot)
    local exhaustedNextID = exhaustedRoot.account.nextProfileID
    local exhaustedEnv, _, exhaustedTest = loadStatsPro("enUS", {
        statsProDB = exhaustedRoot,
        unitGUID = function()
            if exhaustedReady then return "Player-1-NEW-COLD" end
            return nil
        end,
        unitFullName = function() return "NewCold", "Realm" end,
        getSpecialization = function() return 1 end,
        getSpecializationInfo = function()
            return 73, "Protection", nil, nil, "TANK", 1
        end,
    })
    fireEvent("profiles.bootstrap.exhausted.pending", exhaustedEnv, "PLAYER_ENTERING_WORLD")
    exhaustedEnv.__flushTimers(1)
    runtime = exhaustedTest.profileRuntimeState()
    eq("profiles.bootstrap.exhausted.read_bound", runtime.contextReadCount, 4)
    eq("profiles.bootstrap.exhausted.retry_bound", runtime.contextRetryCount, 3)
    eq("profiles.bootstrap.exhausted.no_timer", runtime.contextRetryScheduled, false)
    eq("profiles.bootstrap.exhausted.stays_pending", runtime.pendingResolution, true)
    eq("profiles.bootstrap.exhausted.not_loaded", runtime.isLoaded, false)
    assertDeepEqual("profiles.bootstrap.exhausted.no_writes", exhaustedRoot, exhaustedBefore)
    exhaustedReady = true
    fireEvent("profiles.bootstrap.exhausted.authoritative_retry",
        exhaustedEnv, "PLAYER_REGEN_ENABLED")
    runtime = exhaustedTest.profileRuntimeState()
    eq("profiles.bootstrap.exhausted.loaded", runtime.isLoaded, true)
    eq("profiles.bootstrap.exhausted.pending_cleared", runtime.pendingResolution, false)
    eq("profiles.bootstrap.exhausted.retry_cleared", runtime.contextRetryCount, 0)
    eq("profiles.bootstrap.exhausted.one_activation", runtime.activationCount, 1)
    eq("profiles.bootstrap.exhausted.one_character",
        exhaustedRoot.characters["Player-1-NEW-COLD"] ~= nil, true)
    eq("profiles.bootstrap.exhausted.one_profile_allocation",
        exhaustedRoot.account.nextProfileID, exhaustedNextID + 1)
    eq("profiles.bootstrap.exhausted.no_hidden_default",
        exhaustedRoot.characters["Player-1-NEW-COLD"].defaultProfileID, nil)
    local recoveredNextID = exhaustedRoot.account.nextProfileID
    fireEvent("profiles.bootstrap.exhausted.same_context",
        exhaustedEnv, "PLAYER_ENTERING_WORLD")
    exhaustedEnv.__flushTimers(0)
    eq("profiles.bootstrap.exhausted.no_duplicate_allocation",
        exhaustedRoot.account.nextProfileID, recoveredNextID)
    eq("profiles.bootstrap.exhausted.no_duplicate_activation",
        exhaustedTest.profileRuntimeState().activationCount, 1)

    local staleReady = false
    local staleRoot = makeColdRoot(false)
    local staleEnv, _, staleTest = loadStatsPro("enUS", {
        statsProDB = staleRoot,
        unitGUID = function()
            if staleReady then return "Player-1-STALE-COLD" end
            return nil
        end,
        getSpecialization = function() return 1 end,
        getSpecializationInfo = function()
            return 73, "Protection", nil, nil, "TANK", 1
        end,
    })
    fireEvent("profiles.bootstrap.stale.pending", staleEnv, "PLAYER_ENTERING_WORLD")
    local staleGeneration = staleTest.profileRuntimeState().requestGeneration
    staleReady = true
    fireEvent("profiles.bootstrap.stale.new_generation", staleEnv, "PLAYER_ENTERING_WORLD")
    runtime = staleTest.profileRuntimeState()
    local staleNextID = staleRoot.account.nextProfileID
    eq("profiles.bootstrap.stale.newer_generation",
        runtime.requestGeneration > staleGeneration, true)
    eq("profiles.bootstrap.stale.one_activation", runtime.activationCount, 1)
    staleEnv.__flushTimers(0.25)
    runtime = staleTest.profileRuntimeState()
    eq("profiles.bootstrap.stale.old_timer_no_activation", runtime.activationCount, 1)
    eq("profiles.bootstrap.stale.old_timer_no_allocation",
        staleRoot.account.nextProfileID, staleNextID)
    eq("profiles.bootstrap.stale.pending_cleared", runtime.pendingResolution, false)
end

do
    -- A first-seen specialization gets one bounded, unique profile name without
    -- allocating a hidden character-default profile.
    local seed, _, seedTest = loadStatsPro("enUS")
    fireEvent("profiles.context.auto_name.seed", seed, "PLAYER_ENTERING_WORLD")
    local root = deepCopy(seed.StatsProDB)
    local playerName = string.rep("界", 25)
    local realmName = string.rep("界", 2)
    local displayName = playerName .. "-" .. realmName
    local specName = string.rep("Ж", 25)
    local context = { displayName = displayName, specID = 999, specName = specName }
    local nextID = root.account.nextProfileID
    local specCollision = seedTest.profileOps.specProfileName(context, root.profiles)
    root.profiles["p" .. tostring(nextID)] = {
        name = specCollision,
        settings = deepCopy(root.profiles.p1.settings),
    }
    nextID = nextID + 1
    root.account.nextProfileID = nextID

    local env, _, test = loadStatsPro("enUS", {
        statsProDB = root,
        unitGUID = function() return "Player-1-AUTO-NAME" end,
        unitFullName = function() return playerName, realmName end,
        getSpecialization = function() return 1 end,
        getSpecializationInfo = function()
            return 999, specName, nil, nil, "TANK", 1
        end,
    })
    fireEvent("profiles.context.auto_name.activate", env, "PLAYER_ENTERING_WORLD")
    local character = root.characters["Player-1-AUTO-NAME"]
    local specID = character.specProfiles[999]
    local generatedSpecName = root.profiles[specID].name
    local normalized, count = test.profileOps.normalizeName(
        generatedSpecName, root.profiles, specID)
    eq("profiles.context.auto_name.no_hidden_default", character.defaultProfileID, nil)
    eq("profiles.context.auto_name.spec_valid", normalized, generatedSpecName)
    eq("profiles.context.auto_name.spec_bounded", count <= 40, true)
    eq("profiles.context.auto_name.spec_collision_resolved",
        generatedSpecName ~= specCollision, true)
    eq("profiles.context.auto_name.one_allocation", root.account.nextProfileID, nextID + 1)
    eq("profiles.context.auto_name.no_orphan",
        root.profiles["p" .. tostring(nextID + 1)], nil)
end

do
    -- One remaining allocatable ID is sufficient for a first-seen specialization.
    -- A hidden character-default clone used to consume it before the useful profile.
    local seed = loadStatsPro("enUS")
    fireEvent("profiles.context.last_id.seed", seed, "PLAYER_ENTERING_WORLD")
    local root = deepCopy(seed.StatsProDB)
    local lastAllocatableNumber = 99999999999998
    root.account.nextProfileID = lastAllocatableNumber
    local env, _, test = loadStatsPro("enUS", {
        statsProDB = root,
        unitGUID = function() return "Player-1-LAST-ID" end,
        unitFullName = function() return "Last", "Realm" end,
        getSpecialization = function() return 1 end,
        getSpecializationInfo = function()
            return 999, "Last Spec", nil, nil, "TANK", 1
        end,
    })
    fireEvent("profiles.context.last_id.activate", env, "PLAYER_ENTERING_WORLD")
    local character = root.characters["Player-1-LAST-ID"]
    local profileID = "p" .. tostring(lastAllocatableNumber)
    eq("profiles.context.last_id.character_created", type(character), "table")
    eq("profiles.context.last_id.no_hidden_default", character.defaultProfileID, nil)
    eq("profiles.context.last_id.assignment", character.specProfiles[999], profileID)
    eq("profiles.context.last_id.active", test.profileState().profileID, profileID)
    eq("profiles.context.last_id.next_at_limit", root.account.nextProfileID, 99999999999999)
    eq("profiles.context.last_id.profile_exists", type(root.profiles[profileID]), "table")
    eq("profiles.context.last_id.pending_cleared", test.profileRuntimeState().pendingResolution, false)
end

do
    -- Name-space exhaustion during first visit is preparation-only: no ID, profile,
    -- character assignment, or runtime activation can leak into the live registry.
    local seed, _, seedTest = loadStatsPro("enUS")
    fireEvent("profiles.context.auto_name_exhausted.seed", seed, "PLAYER_ENTERING_WORLD")
    local root = deepCopy(seed.StatsProDB)
    local context = { displayName = "Collision-Realm", specID = 999, specName = "Collision" }
    local collisionName = seedTest.profileOps.specProfileName(context, root.profiles)
    local collisionID = "p" .. tostring(root.account.nextProfileID)
    root.profiles[collisionID] = {
        name = collisionName,
        settings = deepCopy(root.profiles.p1.settings),
    }
    root.account.nextProfileID = root.account.nextProfileID + 1
    local env, _, test = loadStatsPro("enUS", {
        statsProDB = root,
        unitGUID = function() return "Player-1-AUTO-NAME-EXHAUSTED" end,
        unitFullName = function() return "Collision", "Realm" end,
        getSpecialization = function() return 1 end,
        getSpecializationInfo = function()
            return 999, "Collision", nil, nil, "TANK", 1
        end,
    })
    test.profileOps.setMaxUniqueNameCandidates(1)
    local before = deepCopy(root)
    local accountRef, profilesRef, charactersRef = root.account, root.profiles, root.characters
    fireEvent("profiles.context.auto_name_exhausted.activate", env, "PLAYER_ENTERING_WORLD")
    assertDeepEqual("profiles.context.auto_name_exhausted.no_writes", root, before)
    eq("profiles.context.auto_name_exhausted.account_identity", root.account, accountRef)
    eq("profiles.context.auto_name_exhausted.profiles_identity", root.profiles, profilesRef)
    eq("profiles.context.auto_name_exhausted.characters_identity", root.characters, charactersRef)
    eq("profiles.context.auto_name_exhausted.no_character",
        root.characters["Player-1-AUTO-NAME-EXHAUSTED"], nil)
    eq("profiles.context.auto_name_exhausted.no_activation",
        test.profileRuntimeState().activationCount, 0)
    eq("profiles.context.auto_name_exhausted.pending",
        test.profileRuntimeState().pendingResolution, true)
    test.profileOps.setMaxUniqueNameCandidates(9999)
end

do
    -- Old current-schema registries may already contain duplicate, overlong, or
    -- pre-contract separator-bearing names.
    -- They stay writable and untouched; only newly generated names use the new contract.
    local seed = loadStatsPro("enUS")
    fireEvent("profiles.context.legacy_name.seed", seed, "PLAYER_ENTERING_WORLD")
    local root = deepCopy(seed.StatsProDB)
    local legacyName = string.rep("界", 41) .. string.char(0xE3, 0x80, 0x80)
    root.profiles.p2 = { name = legacyName, settings = deepCopy(root.profiles.p1.settings) }
    root.profiles.p3 = { name = legacyName, settings = deepCopy(root.profiles.p1.settings) }
    root.account.nextProfileID = 4
    root.characters["Player-1-LEGACY-NAME"] = {
        displayName = "Legacy-Realm",
        classID = 1,
        lastSeen = 1,
        defaultProfileID = "p1",
        specProfiles = { [73] = "p1" },
    }
    local before = deepCopy(root)
    local accountRef, profilesRef, p2Ref, p3Ref =
        root.account, root.profiles, root.profiles.p2, root.profiles.p3
    local env, _, test = loadStatsPro("enUS", {
        statsProDB = root,
        unitGUID = function() return "Player-1-LEGACY-NAME" end,
        unitFullName = function() return "Legacy", "Realm" end,
        getServerTime = function() return 1 end,
        getSpecialization = function() return 1 end,
        getSpecializationInfo = function()
            return 73, "Protection", nil, nil, "TANK", 1
        end,
    })
    fireEvent("profiles.context.legacy_name.load", env, "PLAYER_ENTERING_WORLD")
    eq("profiles.context.legacy_name.mode", test.dbCompatibilityState().mode, "current")
    eq("profiles.context.legacy_name.writable", test.dbCompatibilityState().readOnly, false)
    assertDeepEqual("profiles.context.legacy_name.unchanged", root, before)
    eq("profiles.context.legacy_name.account_identity", root.account, accountRef)
    eq("profiles.context.legacy_name.profiles_identity", root.profiles, profilesRef)
    eq("profiles.context.legacy_name.p2_identity", root.profiles.p2, p2Ref)
    eq("profiles.context.legacy_name.p3_identity", root.profiles.p3, p3Ref)
    root.profiles.p2.settings.showDefensive = true
    local ok, profileID = test.profileOps.resetProfile("p2")
    check("profiles.context.legacy_name.reset_ok", ok, profileID)
    eq("profiles.context.legacy_name.reset_name",
        root.profiles[profileID].name, legacyName)
    eq("profiles.context.legacy_name.reset_payload",
        root.profiles[profileID].settings.showDefensive, false)
    eq("profiles.context.legacy_name.old_duplicate_preserved",
        root.profiles.p2.name, legacyName)
end

do
    local seed = loadStatsPro("enUS")
    fireEvent("profiles.context.invalid.seed", seed, "PLAYER_ENTERING_WORLD")
    local cleanRoot = deepCopy(seed.StatsProDB)
    local secretGUID = {}
    local invalidEnv, _, invalidTest = loadStatsPro("enUS", {
        statsProDB = cleanRoot,
        unitGUID = function() return secretGUID end,
        getSpecialization = function() return 1 end,
        getSpecializationInfo = function() return 73, "Protection", nil, nil, "TANK", 1 end,
        issecretvalue = function(value) return value == secretGUID end,
    })
    local before = deepCopy(cleanRoot)
    fireEvent("profiles.context.invalid.secret_guid", invalidEnv, "PLAYER_ENTERING_WORLD")
    assertDeepEqual("profiles.context.invalid.secret_guid.no_writes", cleanRoot, before)
    eq("profiles.context.invalid.secret_guid.no_activation",
        invalidTest.profileRuntimeState().activationCount, 0)
    slash("profiles.context.invalid.secret_guid.block_write", invalidEnv, "hide")
    fireEvent("profiles.context.invalid.secret_guid.logout", invalidEnv, "PLAYER_LOGOUT")
    assertDeepEqual("profiles.context.invalid.secret_guid.pending_blocks_all_writes", cleanRoot, before)

    local noSpecRoot = deepCopy(seed.StatsProDB)
    local noSpecBefore = deepCopy(noSpecRoot)
    local noSpecEnv, _, noSpecTest = loadStatsPro("enUS", {
        statsProDB = noSpecRoot,
        unitGUID = function() return "Player-1-NOSPEC" end,
        getSpecialization = function() return nil end,
    })
    fireEvent("profiles.context.invalid.no_spec_initial", noSpecEnv, "PLAYER_ENTERING_WORLD")
    eq("profiles.context.invalid.no_spec_initial.no_character",
