    {
        name = "reset",
        key = "STATSPRO_RESET_ACTIVE_PROFILE",
        pendingField = "resetPending",
        open = function(env, suffix)
            slash("profiles.compat.combat_cancel.stale_reopen.reset." .. suffix, env, "reset")
        end,
    },
